'use strict';

// MODULES //

var sindf = require( '@stdlib/math/base/special/sindf' );
var cosdf = require( '@stdlib/math/base/special/cosdf' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );


// MAIN //

/**
* Simultaneously computes the sine and cosine of an angle measured in degrees and assigns the results to a provided output array (single-precision).
*
* @private
* @param {number} x - input value (in degrees)
* @param {Collection} out - output array
* @param {integer} stride - output array stride
* @param {NonNegativeInteger} offset - output array index offset
* @returns {Collection} output array
*
* @example
* var v = sincosdf( 0.0, [ 0.0, 0.0 ], 1, 0 );
* // returns [ ~0.0, ~1.0 ]
*
* @example
* var v = sincosdf( 90.0, [ 0.0, 0.0 ], 1, 0 );
* // returns [ ~1.0, ~0.0 ]
*
* @example
* var v = sincosdf( -30.0, [ 0.0, 0.0 ], 1, 0 );
* // returns [ ~-0.5, ~0.8660254 ]
*
* @example
* var v = sincosdf( NaN, [ 0.0, 0.0 ], 1, 0 );
* // returns [ NaN, NaN ]
*/
function sincosdf( x, out, stride, offset ) {
	out[ offset ] = f32( sindf( x ) );
	out[ offset + stride ] = f32( cosdf( x ) );
	return out;
}


// EXPORTS //

module.exports = sincosdf;
